	 ('KARMA_02','SKACT',100,5.0,'TG03','TP02','번뇌','STDB01','최종 회피 감소 및 도발 디버프',75.00,'%',5.0,'범위','지속시간 동안 도발 상태','피안의 빛 공격 성공 시, 피격 대상에게 5초 동안 최종 회피 75% 감소 디버프 및 도발 상태를 부여합니다.','N',10),
