	 ('KV_B','SKCT',60,NULL,'TG02',NULL,'아그니의 긍지','STB08','최종 치명타 피해 증가',24.00,'%',2.0,'단일',NULL,'이군(아군)에게 2초 동안 최종 치명타 피해 24% 증가 버프 부여.','N',10),
	 ('KV_B','SKCT',60,NULL,'TG01',NULL,'불의 연무','STB08','최종 치명타 피해 및 공속 증가',50.00,'%',1.0,'단일',NULL,'자신이 과부하 상태일 때, 1초 동안 최종 치명타 피해 50% 증가, 공격속도 50% 증가.','N',10),
